from pathlib import Path

def get(path):
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"ERROR: Missing {path}. Run from repo root.")
    return p, p.read_text(encoding="utf-8")

# contribution/actions.ts
p, src = get("app/(portal)/contribution/actions.ts")
history_code = '\nexport type ContributionHistoryEntry = {\n  id: string;\n  amountMinor: number;\n  currency: string;\n  status: string;\n  createdAt: string;\n  paidAt: string | null;\n};\n\nexport type ContributionHistoryResult = {\n  email: string | null;\n  entries: ContributionHistoryEntry[];\n};\n\nexport async function getMyContributionHistory(): Promise<ContributionHistoryResult> {\n  const supabase = await createClient();\n  const admin = createAdminClient();\n\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    return { email: null, entries: [] };\n  }\n\n  const email = user.email?.trim() ?? "";\n\n  if (!email) {\n    return { email: null, entries: [] };\n  }\n\n  const { data, error } = await admin\n    .from("support_contributions")\n    .select("id, amount_minor, currency, status, created_at, paid_at")\n    .eq("customer_email", email)\n    .order("created_at", { ascending: false })\n    .limit(50);\n\n  if (error) {\n    throw new Error(error.message);\n  }\n\n  return {\n    email,\n    entries: (data ?? []).map((row) => ({\n      id: String(row.id),\n      amountMinor: Number(row.amount_minor),\n      currency: String(row.currency ?? "GBP").toUpperCase(),\n      status: String(row.status ?? "pending"),\n      createdAt: String(row.created_at),\n      paidAt: row.paid_at ? String(row.paid_at) : null,\n    })),\n  };\n}\n'
if "export async function getMyContributionHistory()" not in src:
    p.write_text(src.rstrip() + "\n" + history_code + "\n", encoding="utf-8")

# contribution checkout event
p, src = get("components/contributions/contribution-checkout.tsx")
old = '          onPaid={() => {\n            setCompletedAmount(state.amountMinor);\n            setCheckoutOpen(false);\n          }}\n'
new = '          onPaid={() => {\n            setCompletedAmount(state.amountMinor);\n            setCheckoutOpen(false);\n            window.dispatchEvent(\n              new CustomEvent("sepulchria:contribution-updated"),\n            );\n          }}\n'
if "sepulchria:contribution-updated" not in src:
    if src.count(old) != 1:
        raise SystemExit("ERROR: Could not uniquely find contribution onPaid callback.")
    p.write_text(src.replace(old, new, 1), encoding="utf-8")

# portal context panel
p, src = get("components/portal/portal-context-panel.tsx")
import_old = 'import {\n  shapeSchoolBorderClass,\n} from "@/lib/warping/shape-school-style";\n'
import_new = 'import {\n  shapeSchoolBorderClass,\n} from "@/lib/warping/shape-school-style";\nimport {\n  getMyContributionHistory,\n  type ContributionHistoryEntry,\n} from "@/app/(portal)/contribution/actions";\n'
if "getMyContributionHistory" not in src:
    if src.count(import_old) != 1:
        raise SystemExit("ERROR: Could not uniquely find contribution context import anchor.")
    src = src.replace(import_old, import_new, 1)
route_old = 'if (pathname === "/cosmetics") {\n  return <PlayerCosmeticsContextPanel />;\n}\n\nif (pathname === "/ranking") {\n'
route_new = 'if (pathname === "/cosmetics") {\n  return <PlayerCosmeticsContextPanel />;\n}\n\nif (pathname === "/contribution") {\n  return <ContributionHistoryContext />;\n}\n\nif (pathname === "/ranking") {\n'
if 'pathname === "/contribution"' not in src:
    if src.count(route_old) != 1:
        raise SystemExit("ERROR: Could not uniquely find contribution context route anchor.")
    src = src.replace(route_old, route_new, 1)
component = '\nfunction contributionMoney(amountMinor: number, currency: string) {\n  return new Intl.NumberFormat("en-GB", {\n    style: "currency",\n    currency,\n  }).format(amountMinor / 100);\n}\n\nfunction contributionDate(value: string) {\n  const date = new Date(value);\n\n  if (Number.isNaN(date.getTime())) {\n    return value;\n  }\n\n  return new Intl.DateTimeFormat("en-GB", {\n    day: "2-digit",\n    month: "short",\n    year: "numeric",\n    hour: "2-digit",\n    minute: "2-digit",\n  }).format(date);\n}\n\nfunction ContributionHistoryContext() {\n  const [email, setEmail] = useState<string | null>(null);\n  const [entries, setEntries] = useState<ContributionHistoryEntry[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n\n  const loadHistory = useCallback(async () => {\n    try {\n      setError(null);\n      const result = await getMyContributionHistory();\n      setEmail(result.email);\n      setEntries(result.entries);\n    } catch (loadError) {\n      setError(\n        loadError instanceof Error\n          ? loadError.message\n          : "Unable to load contribution history.",\n      );\n    } finally {\n      setLoading(false);\n    }\n  }, []);\n\n  useEffect(() => {\n    void loadHistory();\n\n    function handleUpdated() {\n      void loadHistory();\n    }\n\n    function handleFocus() {\n      void loadHistory();\n    }\n\n    window.addEventListener(\n      "sepulchria:contribution-updated",\n      handleUpdated,\n    );\n    window.addEventListener("focus", handleFocus);\n\n    return () => {\n      window.removeEventListener(\n        "sepulchria:contribution-updated",\n        handleUpdated,\n      );\n      window.removeEventListener("focus", handleFocus);\n    };\n  }, [loadHistory]);\n\n  const paidEntries = entries.filter(\n    (entry) => entry.status === "paid",\n  );\n\n  const paidTotalMinor = paidEntries.reduce(\n    (total, entry) => total + entry.amountMinor,\n    0,\n  );\n\n  const totalCurrency =\n    paidEntries[0]?.currency ?? entries[0]?.currency ?? "GBP";\n\n  return (\n    <div className="flex h-full min-h-0 flex-col">\n      <ContextHeading\n        eyebrow="Support Sepulchria"\n        title="Your contributions"\n      />\n\n      <div className="border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-100c09))] px-3 py-3">\n        <p className="text-[8px] normal-case tracking-[0.06em] text-[rgb(var(--sep-colour-806b50))]">\n          Account email\n        </p>\n\n        <p className="mt-1 break-all text-[11px] text-[rgb(var(--sep-colour-cbb28a))]">\n          {email ?? "No email available"}\n        </p>\n\n        <div className="mt-3 flex items-end justify-between gap-3 border-t border-[rgb(var(--sep-colour-59432c))]/30 pt-3">\n          <div>\n            <p className="text-[8px] normal-case tracking-[0.06em] text-[rgb(var(--sep-colour-806b50))]">\n              Paid contributions\n            </p>\n            <p className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d8bf91))]">\n              {paidEntries.length}\n            </p>\n          </div>\n\n          <div className="text-right">\n            <p className="text-[8px] normal-case tracking-[0.06em] text-[rgb(var(--sep-colour-806b50))]">\n              Total paid\n            </p>\n            <p className="mt-1 font-serif text-xl text-[rgb(var(--sep-colour-d8bf91))]">\n              {contributionMoney(paidTotalMinor, totalCurrency)}\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <div className="my-4 h-px bg-[rgb(var(--sep-colour-59432c))]/35" />\n\n      <p className="mb-2 text-[9px] normal-case tracking-[0.06em] text-[rgb(var(--sep-colour-806b50))]">\n        Contribution history - {entries.length}\n      </p>\n\n      <div\n        data-portal-scroll\n        className="min-h-0 flex-1 space-y-2 overflow-y-auto pr-1"\n      >\n        {loading ? (\n          <p className="px-2 py-3 text-[11px] text-[rgb(var(--sep-colour-8f826f))]">\n            Loading contribution history...\n          </p>\n        ) : error ? (\n          <p className="border border-red-900/45 bg-red-950/20 px-3 py-2 text-[10px] leading-5 text-red-300">\n            {error}\n          </p>\n        ) : entries.length === 0 ? (\n          <p className="border border-[rgb(var(--sep-colour-59432c))]/35 bg-[rgb(var(--sep-colour-100c09))]/60 px-3 py-3 text-[11px] leading-5 text-[rgb(var(--sep-colour-8f826f))]">\n            No contributions have been recorded for this email yet.\n          </p>\n        ) : (\n          entries.map((entry) => {\n            const date = entry.paidAt ?? entry.createdAt;\n\n            const statusClass =\n              entry.status === "paid"\n                ? "text-emerald-300"\n                : entry.status === "pending"\n                  ? "text-amber-300"\n                  : entry.status === "refunded" ||\n                      entry.status === "partially_refunded"\n                    ? "text-sky-300"\n                    : "text-red-300";\n\n            return (\n              <div\n                key={entry.id}\n                className="border border-[rgb(var(--sep-colour-59432c))]/45 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5"\n              >\n                <div className="flex items-start justify-between gap-3">\n                  <span className="font-serif text-[16px] text-[rgb(var(--sep-colour-d8bf91))]">\n                    {contributionMoney(\n                      entry.amountMinor,\n                      entry.currency,\n                    )}\n                  </span>\n\n                  <span className={`text-[9px] normal-case ${statusClass}`}>\n                    {entry.status.replaceAll("_", " ")}\n                  </span>\n                </div>\n\n                <p className="mt-1 text-[9px] text-[rgb(var(--sep-colour-756958))]">\n                  {contributionDate(date)}\n                </p>\n              </div>\n            );\n          })\n        )}\n      </div>\n    </div>\n  );\n}\n\n'
if "function ContributionHistoryContext()" not in src:
    marker = "function DefaultContext() {"
    if src.count(marker) != 1:
        raise SystemExit("ERROR: Could not uniquely find DefaultContext marker.")
    src = src.replace(marker, component + marker, 1)
p.write_text(src, encoding="utf-8")

print("Added /contribution history to the right context sidebar.")
print("Run: npm run build")
